3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year helpers for a year that starts on 1 July. A date on or after 1 July
7	 * belongs to the fiscal year named by that calendar year; an earlier date belongs to
8	 * the previous one.
9	 */
10	public final class FiscalYear {
11	
12	    private FiscalYear() {
13	    }
14	
15	    /** The fiscal year (its starting calendar year) that contains {@code date}. */
16	    public static int of(LocalDate date) {
17	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
18	    }
19	
20	    /** The 'FY&lt;YY&gt;' label for the fiscal year that contains {@code date}. */
21	    public static String label(LocalDate date) {
22	        return String.format("FY%02d", Math.floorMod(of(date), 100));
23	    }
24	}
