5	/**
6	 * Derives an owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>}. TIER is
7	 * {@code PREMIUM} once the membership level reaches 3, otherwise {@code STANDARD}. AREA is
8	 * {@code METRO} when the locality is a known metropolitan region (NSW, VIC or QLD),
9	 * otherwise {@code REGIONAL}.
10	 */
11	public final class OwnerSegment {
12	
13	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
14	
15	    private OwnerSegment() {
16	    }
17	
18	    /** The {@code <TIER>_<AREA>} segment for a membership level and locality. */
19	    public static String of(int membershipLevel, String locality) {
20	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
21	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
22	        return tier + "_" + area;
23	    }
24	}
