261	     *
262	     * @param name to test
263	     * @return true if pet name is already in use
264	     */
265	    public Pet getPet(String name, boolean ignoreNew) {
266	        name = name.toLowerCase();
267	        for (Pet pet : getPetsInternal()) {
268	            if (!ignoreNew || !pet.isNew()) {
269	                String compName = pet.getName();
