286	
287	            .append("id", this.getId())
288	            .append("new", this.isNew())
289	            .append("lastName", this.getLastName())
290	            .append("firstName", this.getFirstName())
291	            .append("address", this.address)
292	            .append("city", this.city)
293	            .append("telephone", this.telephone)
294	            .toString();
295	    }
