9	/**
10	 * Emits the immutable {@code OWNER_CREATED} structured event to the {@code AUDIT} logger,
11	 * carrying a monotonically increasing {@code seq}, the owner id, the owner's current
12	 * primary identifier and the membership level.
13	 *
14	 * <p>The primary identifier is resolved via {@link #primaryIdentifier(Owner)}: today the
15	 * owner's {@code customerCode}, and whatever replaces it later (e.g. the memberId).
16	 */
17	public final class OwnerCreatedEvent {
18	
19	    private static final AtomicLong SEQ = new AtomicLong();
20	
21	    private OwnerCreatedEvent() {
22	    }
23	
24	    /** The owner's current primary identifier. */
25	    public static String primaryIdentifier(Owner owner) {
26	        return owner.getCustomerCode();
27	    }
28	
29	    /** Emits {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}. */
30	    public static void emit(Owner owner, Object membershipLevel) {
31	        LoggerFactory.getLogger("AUDIT").info(
32	            "{\"seq\":{},\"ownerId\":{},\"customerCode\":\"{}\",\"membershipLevel\":\"{}\",\"event\":\"OWNER_CREATED\"}",
33	            SEQ.incrementAndGet(), owner.getId(), primaryIdentifier(owner), membershipLevel);
34	    }
35	}
