7	/**
8	 * Decides the GOLD membership tier: an owner qualifies once their household (owners
9	 * sharing the same {@link Household} id, i.e. the same normalized last name and
10	 * postcode) has three or more members. When it does not apply, the mapper's existing
11	 * BRONZE/SILVER rules stand.
12	 */
13	public final class GoldTier {
14	
15	    private GoldTier() {
16	    }
17	
18	    /** True when {@code owner}'s household has 3+ members among {@code allOwners}. */
19	    public static boolean qualifies(Owner owner, Collection<Owner> allOwners) {
20	        String household = Household.idFor(owner);
21	        return allOwners.stream()
22	            .filter(o -> household.equals(Household.idFor(o)))
23	            .count() >= 3;
24	    }
25	}
