2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Builds an owner's {@code householdId}: a stable identifier shared by every owner
12	 * in the same household, i.e. owners with the same last name and postcode. Derived
13	 * deterministically, so owners with the same last name and postcode always resolve
14	 * to the same value.
15	 */
16	public final class Household {
17	
18	    private Household() {
19	    }
20	
21	    /** The 12 upper-case hex chars of SHA-256 over {@code normalizedLastName + '|' + postcode}. */
22	    public static String idFor(Owner owner) {
23	        String key = normalize(owner.getLastName()) + "|" + (owner.getPostcode() == null ? "" : owner.getPostcode());
24	        try {
25	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
26	            StringBuilder sb = new StringBuilder(12);
27	            for (int i = 0; i < 6; i++) {
28	                sb.append(String.format("%02X", digest[i]));
29	            }
30	            return sb.toString();
31	        }
32	        catch (NoSuchAlgorithmException e) {
33	            throw new IllegalStateException(e);
34	        }
35	    }
36	
37	    private static String normalize(String value) {
38	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
39	    }
40	}
