18	        String base = CustomerCode.assign(owner);
19	        String code = base;
20	        int n = 1;
21	        while (isTaken(code, existing)) {
22	            code = base + "-" + (++n);
23	        }
24	        return code;
25	    }
26	
27	    private static boolean isTaken(String code, Collection<Owner> existing) {
28	        for (Owner other : existing) {
29	            if (code.equals(other.getCustomerCode())) {
30	                return true;
31	            }
32	        }
33	        return false;
