1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes the single Luhn check digit (0-9) over the decimal digits contained in a value,
5	 * ignoring any non-digit characters. Used to derive an owner's {@code checkDigit} from its
6	 * {@code customerCode}.
7	 */
8	public final class CheckDigit {
9	
10	    private CheckDigit() {
11	    }
12	
13	    /** The Luhn check digit over the digits of {@code value}. */
14	    public static int luhn(String value) {
15	        int sum = 0;
16	        boolean dbl = true;
17	        for (int i = value.length() - 1; i >= 0; i--) {
18	            char c = value.charAt(i);
19	            if (c < '0' || c > '9') {
20	                continue;
21	            }
22	            int d = c - '0';
23	            if (dbl && (d *= 2) > 9) {
24	                d -= 9;
25	            }
26	            sum += d;
27	            dbl = !dbl;
28	        }
29	        return (10 - (sum % 10)) % 10;
30	    }
31	}
